    allowed = allowed_positions(q, k, mask)
    h_mat = [[0.0] * k for _ in range(q)]
    d_mat = [[0.0] * k for _ in range(q)]
    for i in range(q):
        for j in allowed[i]:
            acc = 0.0
            for r in range(d):
                acc += g[i * d + r] * vs[j * d + r]
            h_mat[i][j] = acc
    for i in range(q):
        row_sum = 0.0
        for j in allowed[i]:
            row_sum += probs[i * k + j] * h_mat[i][j]
        for j in allowed[i]:
            d_mat[i][j] = probs[i * k + j] * (h_mat[i][j] - row_sum)
    dq = [0.0] * (q * d)
    dk = [0.0] * (k * d)
    dv = [0.0] * (k * d)
    for i in range(q):
        for r in range(d):
            acc = 0.0
            for j in allowed[i]:
                acc += d_mat[i][j] * ks[j * d + r]
            dq[i * d + r] = acc / scale
    for j in range(k):
        for r in range(d):
            acc_k = 0.0
            acc_v = 0.0
            for i in range(q):
                if j in allowed[i]:
                    acc_k += d_mat[i][j] * qs[i * d + r]
                    acc_v += probs[i * k + j] * g[i * d + r]
            dk[j * d + r] = acc_k / scale
            dv[j * d + r] = acc_v
    return dq, dk, dv

